import pandas as pd
import re

def clean(df):
    df = df.copy()

    # --- Region: normalize case variants and typos to allowed values ---
    region_map = {
        'north': 'North', 'east': 'East',
        'Nort': 'North', 'Suoth': 'South', 'Wst': 'West'
    }
    df['Region'] = df['Region'].apply(
        lambda x: region_map.get(x, x) if isinstance(x, str) else x
    )

    # --- Price: strip currency symbols/commas and convert to numeric ---
    df['Price'] = df['Price'].apply(
        lambda x: float(re.sub(r'[^0-9.\-]', '', str(x))) if pd.notna(x) else x
    )

    # --- Date: fix invalid dates (e.g. '2026-14-01' has month > 12, swap day/month) ---
    def fix_date(v):
        if pd.isna(v):
            return v
        s = str(v).strip()
        m = re.match(r'^(\d{4})-(\d{1,2})-(\d{1,2})$', s)
        if m:
            y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
            if mo > 12 and d <= 12:
                mo, d = d, mo
            try:
                return pd.Timestamp(year=y, month=mo, day=d)
            except ValueError:
                return pd.NaT
        try:
            return pd.to_datetime(s)
        except Exception:
            return pd.NaT
    df['Date'] = df['Date'].apply(fix_date)

    # --- Quantity: ensure positive numeric ---
    df['Quantity'] = pd.to_numeric(df['Quantity'], errors='coerce')
    df.loc[df['Quantity'] < 1, 'Quantity'] = pd.NA

    # --- Revenue: recompute where inconsistent with Quantity * Price ---
    df['Revenue'] = pd.to_numeric(df['Revenue'], errors='coerce')
    expected = df['Quantity'] * df['Price']
    bad = df['Revenue'].notna() & expected.notna() & (df['Revenue'] != expected)
    df.loc[bad, 'Revenue'] = expected[bad]

    return df

def answer(df):
    df = clean(df)
    df = df.dropna(subset=['Region', 'Quantity'])
    res = df.groupby('Region')['Quantity'].sum()
    return {str(k): float(v) for k, v in res.items()}
